/** Değişken içeren kalıplar: [desen, çeviri] */
export const AR_DESEN: [RegExp, (m: RegExpExecArray, t: (s: string) => string) => string][] = [
  [/^Sulanmayan (.+) için temel azot ihtiyacı ([\d.,]+) kg\/da\.$/, (m, t) => { const b = (x: string) => x.charAt(0).toLocaleUpperCase('tr-TR') + x.slice(1); return `الاحتياج الأساسي من النيتروجين لمحصول ${t(b(m[1]))} غير المروي: ${m[2]} kg/da.`; }], /* tahil */
  [/^(\d+) su verilen (.+) daha yüksek verim verir; temel azot ihtiyacı ([\d.,]+) kg\/da\.$/, (m, t) => { const b = (x: string) => x.charAt(0).toLocaleUpperCase('tr-TR') + x.slice(1); return `${t(b(m[2]))} الذي يُعطى ${m[1]} ريّات يعطي إنتاجًا أعلى؛ الاحتياج الأساسي من النيتروجين ${m[3]} kg/da.`; }], /* tahil */
  [/^Organik madde %([\d.,]+) \((.+?)\): toprak kendiliğinden az azot verir, azot hedefi ([\d.,]+) kg\/da artırıldı \(toplam ([\d.,]+) kg\/da\)\.$/, (m) => { return `المادة العضوية ${m[1]} % (${({"çok az": "منخفض جدًا", "az": "منخفض", "orta": "متوسط", "iyi": "جيد", "yüksek": "مرتفع", "çok yüksek": "مرتفع جدًا", "yeterli": "كافٍ"} as Record<string, string>)[m[2]] ?? m[2]}): التربة تعطي قليلًا من النيتروجين بنفسها، فرُفع هدف النيتروجين ${m[3]} kg/da (الإجمالي ${m[4]} kg/da).`; }], /* tahil */
  [/^Organik madde %([\d.,]+) \((.+?)\): toprak azotun bir kısmını kendisi verir, azot hedefi ([\d.,]+) kg\/da azaltıldı \(toplam ([\d.,]+) kg\/da\)\.$/, (m) => { return `المادة العضوية ${m[1]} % (${({"çok az": "منخفض جدًا", "az": "منخفض", "orta": "متوسط", "iyi": "جيد", "yüksek": "مرتفع", "çok yüksek": "مرتفع جدًا", "yeterli": "كافٍ"} as Record<string, string>)[m[2]] ?? m[2]}): التربة تعطي جزءًا من النيتروجين بنفسها، فخُفّض هدف النيتروجين ${m[3]} kg/da (الإجمالي ${m[4]} kg/da).`; }], /* tahil */
  [/^Organik madde %([\d.,]+) \(orta\): azot hedefi değiştirilmedi \(toplam ([\d.,]+) kg\/da\)\.$/, (m) => { return `المادة العضوية ${m[1]} % (متوسط): لم يتغير هدف النيتروجين (الإجمالي ${m[2]} kg/da).`; }], /* tahil */
  [/^Fosfor ([\d.,]+) kg\/da \((.+?)\): ekimde ([\d.,]+) kg\/da saf fosfor \(P₂O₅\) verilir\.$/, (m) => { return `الفوسفور ${m[1]} kg/da (${({"çok az": "منخفض جدًا", "az": "منخفض", "orta": "متوسط", "iyi": "جيد", "yüksek": "مرتفع", "çok yüksek": "مرتفع جدًا", "yeterli": "كافٍ"} as Record<string, string>)[m[2]] ?? m[2]}): يُعطى عند الزراعة ${m[3]} kg/da فوسفور صافٍ (P₂O₅).`; }], /* tahil */
  [/^Fosfor ([\d.,]+) kg\/da \((.+?)\): fosforlu gübreye gerek yok\.$/, (m) => { return `الفوسفور ${m[1]} kg/da (${({"çok az": "منخفض جدًا", "az": "منخفض", "orta": "متوسط", "iyi": "جيد", "yüksek": "مرتفع", "çok yüksek": "مرتفع جدًا", "yeterli": "كافٍ"} as Record<string, string>)[m[2]] ?? m[2]}): لا حاجة إلى سماد فوسفاتي.`; }], /* tahil */
  [/^Potasyum ([\d.,]+) kg\/da \((.+?)\): ([\d.,]+) kg\/da saf potasyum \(K₂O\) eklendi\.$/, (m) => { return `البوتاسيوم ${m[1]} kg/da (${({"çok az": "منخفض جدًا", "az": "منخفض", "orta": "متوسط", "iyi": "جيد", "yüksek": "مرتفع", "çok yüksek": "مرتفع جدًا", "yeterli": "كافٍ"} as Record<string, string>)[m[2]] ?? m[2]}): أُضيف ${m[3]} kg/da بوتاسيوم صافٍ (K₂O).`; }], /* tahil */
  [/^Potasyum ([\d.,]+) kg\/da \((.+?)\): potasyumlu gübreye gerek yok\.$/, (m) => { return `البوتاسيوم ${m[1]} kg/da (${({"çok az": "منخفض جدًا", "az": "منخفض", "orta": "متوسط", "iyi": "جيد", "yüksek": "مرتفع", "çok yüksek": "مرتفع جدًا", "yeterli": "كافٍ"} as Record<string, string>)[m[2]] ?? m[2]}): لا حاجة إلى سماد بوتاسي.`; }], /* tahil */
  [/^Çinko ([\d.,]+) mg\/kg \(düşük\): taban gübresi çinkolu seçildi, yapraktan çinko önemli\.$/, (m) => { return `الزنك ${m[1]} mg/kg (منخفض): اختير سماد أساسي يحتوي على الزنك، والزنك الورقي مهم.`; }], /* tahil */
  [/^Çinko ([\d.,]+) mg\/kg \(yeterli\)\.$/, (m) => { return `الزنك ${m[1]} mg/kg (كافٍ).`; }], /* tahil */
  [/^Bor ([\d.,]+) mg\/kg \(düşük\): kanola bora çok ihtiyaç duyar; tomurcuk ve çiçeklenmedeki yapraktan bor \(MICROSENSE Ca & B\) uygulamalarını atlamayın\.$/, (m) => { return `البورون ${m[1]} mg/kg (منخفض): تحتاج الكانولا إلى كثير من البورون؛ لا تُهمل رش البورون الورقي (MICROSENSE Ca & B) في مرحلتي البراعم والإزهار.`; }], /* tahil */
  [/^Bor ([\d.,]+) mg\/kg \(yeterli\); yapraktan bor yine de çiçek tutumunu destekler\.$/, (m) => { return `البورون ${m[1]} mg/kg (كافٍ)؛ ومع ذلك يدعم البورون الورقي عقد القرون.`; }], /* tahil */
  [/^Kanola kükürde çok ihtiyaç duyar \(yaklaşık 4 kg\/da\); plandaki gübreler ≈ ([\d.,]+) kg\/da veriyor, kapsül döneminde yapraktan potasyum ve kükürt uygulamasını atlamayın\.$/, (m) => { return `تحتاج الكانولا إلى كثير من الكبريت (نحو 4 kg/da)؛ الأسمدة في الخطة تعطي ≈ ${m[1]} kg/da، فلا تُهمل رش البوتاسيوم والكبريت الورقي في مرحلة القرون.`; }], /* tahil */
  [/^Bezelye baklagildir; azotun çoğunu kökündeki bakterilerden alır\. Yalnızca ([\d.,]+) kg\/da başlangıç azotu verilir\.$/, (m) => { return `البازلاء من البقوليات وتحصل على معظم نيتروجينها من البكتيريا في جذورها. يُعطى فقط ${m[1]} kg/da نيتروجين بدء.`; }], /* tahil */
  [/^Kireç %([\d.,]+): çinko ve fosfor alımı zorlaşır; fosfor çinkolu taban gübresiyle, azotun bir kısmı kükürtlü gübreyle \(ör\. amonyum sülfat\) verilir\.$/, (m) => `الجير ${m[1]} %: يصعب امتصاص الزنك والفوسفور؛ يُعطى الفوسفور بسماد أساسي يحتوي على الزنك وجزء من النيتروجين بسماد كبريتي (مثل سلفات الأمونيوم).`],
  [/^en az (.+)$/, (m) => `${m[1]} على الأقل`],
  [/^en çok (.+)$/, (m) => `${m[1]} على الأكثر`],
  [/^Bünye: (.+)$/, (m) => `القوام: ${m[1]}`],
  [/^(\d+) saat$/, (m) => `${m[1]} ساعة`],
  [/^(.+) için bu değer olağan dışı görünüyor\.$/, (m) => `تبدو هذه القيمة غير معتادة لـ ${m[1]}.`],
  [/^Kum \+ silt \+ kil toplamı %(.+) çıktı; %100 olmalı\. Değerleri kontrol edin\.$/, (m) => `مجموع الرمل والسلت والطين ${m[1]} %؛ ويجب أن يكون 100 %. راجع القيم.`],
  [/^(.+) bitkisinde (.+) noksanlığı$/, (m, t) => `نقص ${t(m[2].charAt(0).toLocaleUpperCase('tr-TR') + m[2].slice(1))} في ${t(m[1])}`],
  [/^(.+) bitkisinde (.+)$/, (m, t) => `${t(m[2].charAt(0).toLocaleUpperCase('tr-TR') + m[2].slice(1))} في ${t(m[1])}`],
  [/^(.+) bitkisinde$/, (m, t) => `في ${t(m[1].charAt(0).toLocaleUpperCase('tr-TR') + m[1].slice(1))}`],
  [/^Azotlu gübre miktarını biraz azaltın; her 1\.000 m³ su ≈ (.+) kg azot getirir\.$/, (m) => `قلّل السماد النيتروجيني قليلًا؛ كل 1000 م³ من الماء تجلب ≈ ${m[1]} كغ نيتروجين.`],
  [/^([A-Z][A-Za-z]{0,2}\d*) \((.+) Bünyeli\)$/, (m) => `${m[1]} (${m[2]})`],
  [/^([\d.,]+)( puan| [^\s(]+)? (eksik|fazla) \(%([\d.,]+)\)$/, (m) => `${m[1]}${m[2] === ' puan' ? ' نقطة' : m[2] ?? ''} ${m[3] === 'eksik' ? 'أقل' : 'أكثر'} (${m[4]} %)`],
  [/^(.+) noksanlığı$/, (m, t) => `نقص ${t(m[1])}`],
  [/^(.+) bu tuzluluktan etkilenmez\.$/, (m, t) => `${t(m[1])}: لا يتأثر بهذه الملوحة.`],
  [/^Bu tuzlulukta (.+) için beklenen verim yaklaşık %(\d+) \(tuzsuz suya göre\)\.$/, (m, t) => `عند هذه الملوحة تبلغ الغلة المتوقعة لـ ${t(m[1].charAt(0).toLocaleUpperCase('tr-TR') + m[1].slice(1))} نحو ${m[2]} % (مقارنة بالمياه غير المالحة).`],
  [/^(.+) tuza (.+)\.$/, (m, t) => `${t(m[1])}: ${t(m[2])} للملوحة.`],
  [/^(.+) bora (.+) \(sınır (.+)–(.+) mg\/l\)\.$/, (m, t) => `${t(m[1])}: ${t(m[2])} للبورون (الحد ${m[3]}–${m[4]} mg/l).`],
  [/^Toprağa ya da suya jips verin: .*\(sizde ≈ (.+) kg \/ 1\.000 m³\)\.$/, (m) => `أضف الجبس إلى التربة أو المياه: لكل 1 me/l من RSC نحو 86 كغ جبس نقي لكل 1000 م³ من المياه (لديك ≈ ${m[1]} كغ / 1000 م³).`],
  [/^Bitkinin ihtiyacından yaklaşık %(\d+) fazla su verin \(yıkama suyu\); tuz kök bölgesinden uzaklaşır\.$/, (m) => `أعطِ ماءً أكثر من حاجة النبات بنحو ${m[1]} % (ماء الغسيل)؛ فيبتعد الملح عن منطقة الجذور.`],
  [/^Bu su için (.+) sulama daha uygun; imkânınız varsa geçmeyi düşünün\.$/, (m, t) => `${t(m[1].charAt(0).toLocaleUpperCase("tr-TR") + m[1].slice(1))} أنسب لهذه المياه؛ إن أمكنك ففكّر في التحول إليه.`],
  [/^Sodyum ya da klorür yüksek \((.+) me\/l\): yaprak yanığı yapabilir; yalnızca akşam ve gece sulayın\.$/, (m) => `الصوديوم أو الكلوريد مرتفع (${m[1]} me/l): قد يسبب احتراق الأوراق؛ اروِ مساءً وليلًا فقط.`],
];
